/**
 * Sample content for the ui-look output-preview scenes: a two-sheet drawing PDF, a STEP of the
 * bracket (true B-rep with cylindrical holes) and the inspection report workbook generated by the
 * real engine from the look characteristics. All generated here, so no binary fixture is checked
 * in. `seedPreviewContent` stores each in the fake vault bucket under its real SHA-256, so the
 * preview downloads and verifies them exactly as it does in the app.
 */
import type { PerfBackend } from './backend'
import { lookCharacteristics } from './lookInspectionFixtures'

// ---------------------------------------------------------------------------
// The drawing: primitives in sheet units (1700 x 1100, y down), drawn to a PDF and to a canvas.
// ---------------------------------------------------------------------------

type Prim =
  | { t: 'rect'; x: number; y: number; w: number; h: number; lw: number }
  | { t: 'circle'; cx: number; cy: number; r: number; lw: number; dash?: boolean; fill?: boolean }
  | { t: 'line'; x1: number; y1: number; x2: number; y2: number; lw: number }
  | { t: 'text'; x: number; y: number; size: number; text: string; bold?: boolean; anchor?: 'start' | 'middle' | 'end' }

const SHEET_W = 1700
const SHEET_H = 1100

function balloon(n: number, x: number, y: number): Prim[] {
  const tx = x + (x < 850 ? 45 : -45)
  const ty = y + 35
  return [
    { t: 'line', x1: x, y1: y, x2: tx, y2: ty, lw: 1.2 },
    { t: 'circle', cx: tx, cy: ty, r: 3, lw: 1, fill: true },
    { t: 'circle', cx: x, cy: y, r: 17, lw: 1.6 },
    { t: 'text', x, y: y + 6, size: 17, text: String(n), anchor: 'middle' },
  ]
}

function titleBlock(sheet: number): Prim[] {
  const x = 1100
  const y = 900
  return [
    { t: 'rect', x, y, w: 560, h: 160, lw: 2 },
    { t: 'line', x1: x, y1: y + 50, x2: x + 560, y2: y + 50, lw: 1 },
    { t: 'line', x1: x, y1: y + 110, x2: x + 560, y2: y + 110, lw: 1 },
    { t: 'line', x1: x + 380, y1: y + 50, x2: x + 380, y2: y + 160, lw: 1 },
    { t: 'text', x: x + 12, y: y + 33, size: 22, text: 'BRACKET, MOTOR MOUNT', bold: true },
    { t: 'text', x: x + 12, y: y + 72, size: 11, text: 'DWG NO.' },
    { t: 'text', x: x + 12, y: y + 98, size: 22, text: 'BR-103849-201' },
    { t: 'text', x: x + 392, y: y + 72, size: 11, text: 'REV' },
    { t: 'text', x: x + 392, y: y + 98, size: 22, text: 'B' },
    { t: 'text', x: x + 12, y: y + 130, size: 11, text: 'UNLESS OTHERWISE SPECIFIED: X.X +/-0.5  X.XX +/-0.2  ANGLES +/-0.5' },
    { t: 'text', x: x + 12, y: y + 150, size: 11, text: 'MATERIAL 6061-T6  FINISH: ANODIZE BLACK' },
    { t: 'text', x: x + 392, y: y + 140, size: 16, text: `SHEET ${sheet} OF 2` },
  ]
}

const BALLOONS: Record<1 | 2, Array<[number, number, number]>> = {
  1: [
    [1, 470, 180], [2, 760, 240], [3, 300, 430], [4, 610, 420], [5, 690, 360], [6, 960, 300],
    [7, 1010, 360], [8, 330, 700], [9, 520, 780], [10, 1180, 260], [11, 1250, 520], [12, 1300, 640],
  ],
  2: [[18, 420, 300], [19, 600, 260], [20, 1050, 330], [21, 1210, 430], [22, 820, 800]],
}

function sheetPrims(sheet: 1 | 2): Prim[] {
  const views: Prim[] =
    sheet === 1
      ? [
          { t: 'rect', x: 250, y: 200, w: 520, h: 420, lw: 2.5 },
          { t: 'circle', cx: 510, cy: 410, r: 70, lw: 2.5 },
          ...[[330, 280], [690, 280], [330, 540], [690, 540]].map(
            ([cx, cy]): Prim => ({ t: 'circle', cx, cy, r: 14, lw: 2 }),
          ),
          { t: 'line', x1: 250, y1: 160, x2: 770, y2: 160, lw: 1 },
          { t: 'text', x: 510, y: 152, size: 16, text: '120.00 +/-0.10', anchor: 'middle' },
          { t: 'line', x1: 210, y1: 200, x2: 210, y2: 620, lw: 1 },
          { t: 'text', x: 200, y: 415, size: 16, text: '64.50 +/-0.05', anchor: 'end' },
          { t: 'rect', x: 900, y: 200, w: 160, h: 420, lw: 2.5 },
          { t: 'rect', x: 1180, y: 360, w: 440, h: 160, lw: 2.5 },
          { t: 'text', x: 1400, y: 570, size: 16, text: 'SECTION A-A', anchor: 'middle' },
          { t: 'rect', x: 280, y: 720, w: 360, h: 120, lw: 2.5 },
        ]
      : [
          { t: 'rect', x: 300, y: 200, w: 460, h: 320, lw: 2.5 },
          { t: 'circle', cx: 530, cy: 360, r: 120, lw: 2, dash: true },
          { t: 'text', x: 530, y: 560, size: 16, text: 'DETAIL B (2 : 1)', anchor: 'middle' },
          { t: 'rect', x: 940, y: 240, w: 420, h: 300, lw: 2.5 },
          { t: 'text', x: 560, y: 760, size: 15, text: 'NOTES: 1. ANODIZE PER MIL-A-8625 TYPE II, CLASS 2, BLACK.' },
        ]
  return [
    { t: 'rect', x: 20, y: 20, w: SHEET_W - 40, h: SHEET_H - 40, lw: 3 },
    ...views,
    ...BALLOONS[sheet].flatMap(([n, x, y]) => balloon(n, x, y)),
    ...titleBlock(sheet),
  ]
}

/** A 17 x 11 in, two-sheet PDF of the drawing (vector, Helvetica). */
export function samplePdf(): Uint8Array {
  const s = 1224 / SHEET_W
  const X = (x: number) => (x * s).toFixed(2)
  const Y = (y: number) => ((SHEET_H - y) * s).toFixed(2)
  const esc = (text: string) => text.replace(/[\\()]/g, (c) => `\\${c}`)
  const k = 0.5523
  const stream = (prims: Prim[]) => {
    const ops: string[] = ['0.11 0.11 0.11 RG 0.11 0.11 0.11 rg 1 J 1 j']
    for (const p of prims) {
      if (p.t === 'rect') ops.push(`${(p.lw * s).toFixed(2)} w ${X(p.x)} ${Y(p.y + p.h)} ${(p.w * s).toFixed(2)} ${(p.h * s).toFixed(2)} re S`)
      else if (p.t === 'line') ops.push(`${(p.lw * s).toFixed(2)} w ${X(p.x1)} ${Y(p.y1)} m ${X(p.x2)} ${Y(p.y2)} l S`)
      else if (p.t === 'circle') {
        const { cx, cy, r } = p
        const c = (dx: number, dy: number) => `${X(cx + dx)} ${Y(cy + dy)}`
        ops.push(
          `${p.dash ? '[7 4] 0 d ' : ''}${(p.lw * s).toFixed(2)} w ${c(r, 0)} m ` +
            `${c(r, k * r)} ${c(k * r, r)} ${c(0, r)} c ${c(-k * r, r)} ${c(-r, k * r)} ${c(-r, 0)} c ` +
            `${c(-r, -k * r)} ${c(-k * r, -r)} ${c(0, -r)} c ${c(k * r, -r)} ${c(r, -k * r)} ${c(r, 0)} c ${p.fill ? 'f' : 'S'}${p.dash ? ' [] 0 d' : ''}`,
        )
      } else {
        const size = p.size * s
        const width = p.text.length * size * (p.bold ? 0.6 : 0.55)
        const x = p.anchor === 'middle' ? p.x * s - width / 2 : p.anchor === 'end' ? p.x * s - width : p.x * s
        ops.push(`BT /${p.bold ? 'F2' : 'F1'} ${size.toFixed(2)} Tf ${x.toFixed(2)} ${Y(p.y)} Td (${esc(p.text)}) Tj ET`)
      }
    }
    return ops.join('\n')
  }
  const contents = [stream(sheetPrims(1)), stream(sheetPrims(2))]
  const objects = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R 5 0 R] /Count 2 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 1224 792] /Resources << /Font << /F1 7 0 R /F2 8 0 R >> >> /Contents 4 0 R >>',
    `<< /Length ${contents[0].length} >>\nstream\n${contents[0]}\nendstream`,
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 1224 792] /Resources << /Font << /F1 7 0 R /F2 8 0 R >> >> /Contents 6 0 R >>',
    `<< /Length ${contents[1].length} >>\nstream\n${contents[1]}\nendstream`,
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>',
  ]
  let out = '%PDF-1.4\n'
  const offsets: number[] = []
  objects.forEach((body, i) => {
    offsets.push(out.length)
    out += `${i + 1} 0 obj\n${body}\nendobj\n`
  })
  const xref = out.length
  out += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`
  for (const offset of offsets) out += `${String(offset).padStart(10, '0')} 00000 n \n`
  out += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`
  return new TextEncoder().encode(out)
}

/** One drawing sheet as a PNG (what `rasterizePdf` gives the report engine), drawn on a canvas. */
async function sheetPng(sheet: 1 | 2, scale = 2): Promise<{ png: Uint8Array; widthPx: number; heightPx: number }> {
  const canvas = document.createElement('canvas')
  canvas.width = SHEET_W * scale
  canvas.height = SHEET_H * scale
  const ctx = canvas.getContext('2d')
  if (!ctx) throw new Error('no 2d canvas')
  ctx.scale(scale, scale)
  ctx.fillStyle = '#ffffff'
  ctx.fillRect(0, 0, SHEET_W, SHEET_H)
  ctx.strokeStyle = '#1b1b1b'
  ctx.fillStyle = '#1b1b1b'
  for (const p of sheetPrims(sheet)) {
    ctx.setLineDash([])
    if (p.t === 'rect') {
      ctx.lineWidth = p.lw
      ctx.strokeRect(p.x, p.y, p.w, p.h)
    } else if (p.t === 'line') {
      ctx.lineWidth = p.lw
      ctx.beginPath()
      ctx.moveTo(p.x1, p.y1)
      ctx.lineTo(p.x2, p.y2)
      ctx.stroke()
    } else if (p.t === 'circle') {
      ctx.lineWidth = p.lw
      if (p.dash) ctx.setLineDash([10, 6])
      ctx.beginPath()
      ctx.arc(p.cx, p.cy, p.r, 0, Math.PI * 2)
      if (p.fill) ctx.fill()
      else {
        // A balloon's face is white over its leader.
        if (p.r === 17) {
          ctx.fillStyle = '#ffffff'
          ctx.fill()
          ctx.fillStyle = '#1b1b1b'
        }
        ctx.stroke()
      }
    } else {
      ctx.font = `${p.bold ? 'bold ' : ''}${p.size}px Arial, sans-serif`
      ctx.textAlign = p.anchor === 'middle' ? 'center' : p.anchor === 'end' ? 'right' : 'left'
      ctx.fillText(p.text, p.x, p.y)
    }
  }
  return { png: await canvasPng(canvas), widthPx: canvas.width, heightPx: canvas.height }
}

async function canvasPng(canvas: HTMLCanvasElement): Promise<Uint8Array> {
  const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/png'))
  if (!blob) throw new Error('canvas.toBlob gave nothing')
  return new Uint8Array(await blob.arrayBuffer())
}

/** A plain wordmark standing in for an organization's logo. */
async function logoPng(): Promise<Uint8Array> {
  const canvas = document.createElement('canvas')
  canvas.width = 720
  canvas.height = 200
  const ctx = canvas.getContext('2d')
  if (!ctx) throw new Error('no 2d canvas')
  ctx.scale(2, 2)
  ctx.fillStyle = '#ffffff'
  ctx.fillRect(0, 0, 360, 100)
  ctx.fillStyle = '#1f6feb'
  ctx.beginPath()
  ctx.moveTo(20, 70)
  ctx.lineTo(50, 20)
  ctx.lineTo(80, 70)
  ctx.closePath()
  ctx.fill()
  ctx.fillStyle = '#ffffff'
  ctx.beginPath()
  ctx.arc(50, 58, 10, 0, Math.PI * 2)
  ctx.fill()
  ctx.fillStyle = '#0b2545'
  ctx.font = 'bold 40px Arial, sans-serif'
  ctx.fillText('Northwind', 100, 62)
  ctx.fillStyle = '#5c6b7a'
  ctx.font = '14px Arial, sans-serif'
  ctx.fillText('ROBOTICS', 102, 84)
  return canvasPng(canvas)
}

/** The production report's workbook through the real engine, with measured values filled in. */
export async function sampleReportWorkbook(): Promise<Uint8Array> {
  const { builtInTemplates, generateInspectionReport } = await import('@/lib/inspection/excel')
  const template = (await builtInTemplates())[0]
  const rows = lookCharacteristics().map((row, i) => ({ ...row, id: `row-${i + 1}` }))
  return generateInspectionReport({
    template: template.bytes,
    reportId: 'look-preview-report',
    fileId: 'look-file',
    fileVersionId: 'look-version-3',
    rows,
    scalars: {
      PART_NUMBER: 'BR-103849-201',
      PART_NAME: 'Bracket, motor mount',
      DESCRIPTION: 'Bracket, motor mount, 6061-T6',
      REVISION: 'B',
      DRAWING_NAME: 'BR-103849-201.SLDDRW',
      DRAWING_VERSION: '3',
      REPORT_NUMBER: 'BR-103849-201_RevB_PIR1',
      ORG_NAME: 'Northwind Robotics',
      GENERAL_TOLERANCES: 'X.X ±0.5, X.XX ±0.2, angles ±0.5°',
    },
    logo: { bytes: await logoPng(), extension: 'png' },
    drawingPages: [await sheetPng(1), await sheetPng(2)],
    generatedAt: new Date('2026-11-03T10:00:00Z'),
  })
}

// ---------------------------------------------------------------------------
// STEP: the bracket as prisms with true cylindrical holes (AP214 B-rep).
// ---------------------------------------------------------------------------

type V3 = [number, number, number]
type V2 = [number, number]

class StepWriter {
  private lines: string[] = []
  private next = 1
  add(entity: string): number {
    const id = this.next++
    this.lines.push(`#${id}=${entity};`)
    return id
  }
  point(p: V3): number {
    return this.add(`CARTESIAN_POINT('',(${p.map((n) => n.toFixed(4)).join(',')}))`)
  }
  dir(d: V3): number {
    const len = Math.hypot(...d)
    return this.add(`DIRECTION('',(${d.map((n) => (n / len).toFixed(6)).join(',')}))`)
  }
  axis(origin: V3, z: V3, x: V3): number {
    return this.add(`AXIS2_PLACEMENT_3D('',#${this.point(origin)},#${this.dir(z)},#${this.dir(x)})`)
  }
  body(): string {
    return this.lines.join('\n')
  }
}

const add3 = (a: V3, b: V3): V3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]]
const mul3 = (a: V3, k: number): V3 => [a[0] * k, a[1] * k, a[2] * k]
const sub3 = (a: V3, b: V3): V3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]]

/**
 * A solid prism: `outer` (counter-clockwise in u, v) with round `holes`, extruded `depth` along
 * w = u x v from `origin`. Returns the MANIFOLD_SOLID_BREP id.
 */
function prism(
  w: StepWriter,
  frame: { origin: V3; u: V3; v: V3; w: V3 },
  depth: number,
  outer: V2[],
  holes: Array<{ c: V2; r: number }>,
): number {
  const at = (p: V2, z: number): V3 =>
    add3(add3(add3(frame.origin, mul3(frame.u, p[0])), mul3(frame.v, p[1])), mul3(frame.w, z))
  const vertex = (p: V3) => w.add(`VERTEX_POINT('',#${w.point(p)})`)
  const lineEdge = (a: V3, b: V3, va: number, vb: number) => {
    const d = sub3(b, a)
    const line = w.add(`LINE('',#${w.point(a)},#${w.add(`VECTOR('',#${w.dir(d)},${Math.hypot(...d).toFixed(4)})`)})`)
    return w.add(`EDGE_CURVE('',#${va},#${vb},#${line},.T.)`)
  }
  const oe = (edge: number, sense: boolean) => w.add(`ORIENTED_EDGE('',*,*,#${edge},${sense ? '.T.' : '.F.'})`)
  const loop = (edges: number[]) => w.add(`EDGE_LOOP('',(${edges.map((e) => `#${e}`).join(',')}))`)
  const plane = (origin: V3, normal: V3, ref: V3) => w.add(`PLANE('',#${w.axis(origin, normal, ref)})`)
  const face = (bounds: number[], surface: number, sense = true) =>
    w.add(`ADVANCED_FACE('',(${bounds.map((b) => `#${b}`).join(',')}),#${surface},${sense ? '.T.' : '.F.'})`)
  const outerBound = (l: number) => w.add(`FACE_OUTER_BOUND('',#${l},.T.)`)
  const bound = (l: number) => w.add(`FACE_BOUND('',#${l},.T.)`)

  const n = outer.length
  const bottomPts = outer.map((p) => at(p, 0))
  const topPts = outer.map((p) => at(p, depth))
  const bottomV = bottomPts.map(vertex)
  const topV = topPts.map(vertex)
  const bottomE = outer.map((_, i) => lineEdge(bottomPts[i], bottomPts[(i + 1) % n], bottomV[i], bottomV[(i + 1) % n]))
  const topE = outer.map((_, i) => lineEdge(topPts[i], topPts[(i + 1) % n], topV[i], topV[(i + 1) % n]))
  const vertE = outer.map((_, i) => lineEdge(bottomPts[i], topPts[i], bottomV[i], topV[i]))

  const faces: number[] = []
  // Sides: outward normal to the right of travel.
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n
    const du = outer[j][0] - outer[i][0]
    const dv = outer[j][1] - outer[i][1]
    const normal = add3(mul3(frame.u, dv), mul3(frame.v, -du))
    const edgeDir = sub3(bottomPts[j], bottomPts[i])
    const l = loop([oe(bottomE[i], true), oe(vertE[j], true), oe(topE[i], false), oe(vertE[i], false)])
    faces.push(face([outerBound(l)], plane(bottomPts[i], normal, edgeDir)))
  }

  // Holes: two circles, one seam, one cylinder whose surface normal points away from the axis.
  const holeBottom: number[] = []
  const holeTop: number[] = []
  for (const hole of holes) {
    const cb = at(hole.c, 0)
    const ct = at(hole.c, depth)
    const pb = add3(cb, mul3(frame.u, hole.r))
    const pt = add3(ct, mul3(frame.u, hole.r))
    const vb = vertex(pb)
    const vt = vertex(pt)
    const circleB = w.add(`CIRCLE('',#${w.axis(cb, frame.w, frame.u)},${hole.r.toFixed(4)})`)
    const circleT = w.add(`CIRCLE('',#${w.axis(ct, frame.w, frame.u)},${hole.r.toFixed(4)})`)
    const eb = w.add(`EDGE_CURVE('',#${vb},#${vb},#${circleB},.T.)`)
    const et = w.add(`EDGE_CURVE('',#${vt},#${vt},#${circleT},.T.)`)
    const seam = lineEdge(pb, pt, vb, vt)
    const cylinder = w.add(`CYLINDRICAL_SURFACE('',#${w.axis(cb, frame.w, frame.u)},${hole.r.toFixed(4)})`)
    const l = loop([oe(eb, false), oe(seam, true), oe(et, true), oe(seam, false)])
    faces.push(face([outerBound(l)], cylinder, false))
    holeBottom.push(bound(loop([oe(eb, true)])))
    holeTop.push(bound(loop([oe(et, false)])))
  }

  // Bottom (normal -w): the outer loop runs clockwise in u, v. Top (normal +w): counter-clockwise.
  const bottomLoop = loop([...bottomE].reverse().map((e) => oe(e, false)))
  faces.push(face([outerBound(bottomLoop), ...holeBottom], plane(bottomPts[0], mul3(frame.w, -1), frame.u)))
  const topLoop = loop(topE.map((e) => oe(e, true)))
  faces.push(face([outerBound(topLoop), ...holeTop], plane(topPts[0], frame.w, frame.u)))

  const shell = w.add(`CLOSED_SHELL('',(${faces.map((f) => `#${f}`).join(',')}))`)
  return w.add(`MANIFOLD_SOLID_BREP('',#${shell})`)
}

/** The motor-mount bracket: a base plate with five holes and a chamfered flange with two. */
export function sampleStep(): Uint8Array {
  const w = new StepWriter()
  const ctxApp = w.add(`APPLICATION_CONTEXT('automotive design')`)
  w.add(`APPLICATION_PROTOCOL_DEFINITION('international standard','automotive_design',2000,#${ctxApp})`)
  const productCtx = w.add(`PRODUCT_CONTEXT('',#${ctxApp},'mechanical')`)
  const product = w.add(`PRODUCT('BR-103849-201','BR-103849-201','',(#${productCtx}))`)
  const formation = w.add(`PRODUCT_DEFINITION_FORMATION('','',#${product})`)
  const defCtx = w.add(`PRODUCT_DEFINITION_CONTEXT('part definition',#${ctxApp},'design')`)
  const definition = w.add(`PRODUCT_DEFINITION('design','',#${formation},#${defCtx})`)
  const shape = w.add(`PRODUCT_DEFINITION_SHAPE('','',#${definition})`)
  const length = w.add(`(LENGTH_UNIT()NAMED_UNIT(*)SI_UNIT(.MILLI.,.METRE.))`)
  const angle = w.add(`(NAMED_UNIT(*)PLANE_ANGLE_UNIT()SI_UNIT($,.RADIAN.))`)
  const solidAngle = w.add(`(NAMED_UNIT(*)SI_UNIT($,.STERADIAN.)SOLID_ANGLE_UNIT())`)
  const uncertainty = w.add(`UNCERTAINTY_MEASURE_WITH_UNIT(LENGTH_MEASURE(1.E-07),#${length},'distance_accuracy_value','')`)
  const geomCtx = w.add(
    `(GEOMETRIC_REPRESENTATION_CONTEXT(3)GLOBAL_UNCERTAINTY_ASSIGNED_CONTEXT((#${uncertainty}))GLOBAL_UNIT_ASSIGNED_CONTEXT((#${length},#${angle},#${solidAngle}))REPRESENTATION_CONTEXT('',''))`,
  )

  // Base plate: u = +X, v = -Z, extruded 6 mm up +Y.
  const plate = prism(
    w,
    { origin: [0, 0, 0], u: [1, 0, 0], v: [0, 0, -1], w: [0, 1, 0] },
    6,
    [[0, 0], [120, 0], [120, 64.5], [0, 64.5]],
    [
      { c: [14, 50.5], r: 4.25 },
      { c: [106, 50.5], r: 4.25 },
      { c: [14, 24], r: 4.25 },
      { c: [106, 24], r: 4.25 },
      { c: [60, 40], r: 14 },
    ],
  )
  // Flange on the far edge: u = +X, v = +Y, extruded 6 mm along +Z from z = -64.5.
  const flange = prism(
    w,
    { origin: [0, 0, -64.5], u: [1, 0, 0], v: [0, 1, 0], w: [0, 0, 1] },
    6,
    [[0, 6], [120, 6], [120, 46], [108, 58], [12, 58], [0, 46]],
    [
      { c: [30, 34], r: 3.3 },
      { c: [90, 34], r: 3.3 },
    ],
  )
  const origin = w.axis([0, 0, 0], [0, 0, 1], [1, 0, 0])
  const rep = w.add(`ADVANCED_BREP_SHAPE_REPRESENTATION('',(#${plate},#${flange},#${origin}),#${geomCtx})`)
  w.add(`SHAPE_DEFINITION_REPRESENTATION(#${shape},#${rep})`)

  const text = [
    'ISO-10303-21;',
    'HEADER;',
    "FILE_DESCRIPTION(('BluePLM ui-look sample'),'2;1');",
    "FILE_NAME('BR-103849-201_RevB.step','2026-11-03T00:00:00',(''),(''),'','','');",
    "FILE_SCHEMA(('AUTOMOTIVE_DESIGN { 1 0 10303 214 1 1 1 1 }'));",
    'ENDSEC;',
    'DATA;',
    w.body(),
    'ENDSEC;',
    'END-ISO-10303-21;',
    '',
  ].join('\n')
  return new TextEncoder().encode(text)
}

// ---------------------------------------------------------------------------
// Seeding
// ---------------------------------------------------------------------------

export interface SeededContent {
  hash: string
  size: number
}

async function sha256(bytes: Uint8Array): Promise<string> {
  const copy = new Uint8Array(bytes.byteLength)
  copy.set(bytes)
  const digest = await crypto.subtle.digest('SHA-256', copy.buffer)
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('')
}

/** Store `bytes` in the fake vault bucket where `downloadFile` reads it (`vault/<org>/<hash>`). */
export async function seedContent(backend: PerfBackend, orgId: string, bytes: Uint8Array): Promise<SeededContent> {
  const hash = await sha256(bytes)
  backend.db.storeObject(`vault/${orgId}/${hash}`, bytes)
  return { hash, size: bytes.byteLength }
}
